def slugify(s):
    s=s.lower().replace('&',' and ').replace('nextjs','nextjs')
    return re.sub(r'-+','-',re.sub(r'[^a-z0-9]+','-',s)).strip('-')

pillars=[]
all_records=[]
for slug, group in GROUPS.items():
    pillars.append({k: group[k] for k in ['slug','title','summary','service']})
    for row in group['rows']:
        row['slug']=slugify(row['title'])
        row['pillar']=slug
        all_records.append(row)
if len(all_records)!=320: raise RuntimeError(f'expected 320, got {len(all_records)}')
paths=[f"/playbooks/{item['pillar']}/{item['slug']}" for item in all_records]
if len(paths)!=len(set(paths)): raise RuntimeError('duplicate path')
(ROOT/'data'/'playbooks.json').write_text(json.dumps({'pillars':pillars,'guides':all_records},indent=2,ensure_ascii=False)+'\n')
print(f'generated {len(all_records)} distinct editorial playbooks in {len(pillars)} clusters')
